<script setup lang="ts">
import {ref,reactive,watch} from 'vue'
import {ElMessage} from 'element-plus'
import type {Row} from '../api/types'
import {post} from '../api/http'
import {useMutation,number,confirmAction} from '../composables/useResource'
import {useMediaQuery} from '../composables/useMediaQuery'
const props=defineProps<{modelValue:boolean;title:string;endpoint:string;items:Row[];hint:string}>()
const emit=defineEmits<{'update:modelValue':[boolean];saved:[]}>()
const isMobile=useMediaQuery(),form=reactive({reference:'',reason:''}),lines=ref<(Row&{quantity:number})[]>([]),{saving,run}=useMutation()
watch(()=>props.modelValue,open=>{if(open){form.reference='';form.reason='';lines.value=props.items.filter(i=>Number(i.returnable_quantity)>0).map(i=>({...i,quantity:0}))}})
async function save(){const selected=lines.value.filter(i=>i.quantity>0);if(!form.reference.trim()||!form.reason.trim()||!selected.length||selected.some(i=>!Number.isFinite(i.quantity)||i.quantity>Number(i.returnable_quantity))){ElMessage.warning('请填写唯一凭证、原因，并选择有效的退回数量');return}if(!await confirmAction('确认办理本次退回？原单据保留，库存和相关金额由服务端入账。'))return;if(await run(()=>post(props.endpoint,{...form,items:selected.map(i=>({source_id:i.id,quantity:i.quantity}))}),'退回单据已入账')){emit('update:modelValue',false);emit('saved')}}
</script>
<template><el-dialog :model-value="modelValue" :title="title" width="860px" :close-on-click-modal="false" destroy-on-close @update:model-value="emit('update:modelValue',$event)"><el-alert :title="hint" type="info" show-icon :closable="false" class="mb"/><el-form label-position="top"><div class="form-grid"><el-form-item label="退回凭证号 *"><el-input v-model="form.reference" maxlength="100" placeholder="填写本次退回的唯一凭证号"/></el-form-item><el-form-item label="退回原因 *"><el-input v-model="form.reason" maxlength="1000" placeholder="说明退回原因"/></el-form-item></div><div v-if="isMobile" class="mobile-form-lines"><section v-for="line in lines" :key="line.id" class="mobile-form-line"><h3>{{line.material_name}}</h3><p class="field-hint">{{line.specification}} · 可退 {{number(line.returnable_quantity)}} {{line.unit}}</p><el-form-item label="本次退回数量"><el-input-number v-model="line.quantity" :min="0" :max="Number(line.returnable_quantity)" :precision="3" controls-position="right" style="width:100%"/></el-form-item></section></div><el-table v-else :data="lines" border><el-table-column prop="material_name" label="材料名称" min-width="170"/><el-table-column prop="specification" label="规格型号"/><el-table-column label="可退数量"><template #default="{row}">{{number(row.returnable_quantity)}} {{row.unit}}</template></el-table-column><el-table-column label="本次退回数量" width="220"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0" :max="Number(row.returnable_quantity)" :precision="3" controls-position="right"/></template></el-table-column></el-table><el-empty v-if="!lines.length" description="该单据没有可退材料" :image-size="60"/><p class="field-hint">按原单据校验累计可退数量；金额由服务端计算，分次退回保留尾差。</p></el-form><template #footer><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="saving" :disabled="!lines.length" @click="save">确认退回并入账</el-button></template></el-dialog></template>
